export const legalGuideBySlug = (slug: string) =>
  legalGuides.find((guide) => guide.slug === slug);

export const legalGuidesForPractice = (practiceKey: string) =>
  [
    ...legalGuides.filter((guide) => guide.practiceKey === practiceKey),
    ...legalGuides.filter(
      (guide) =>
        guide.practiceKey === 'personal-injury' &&
        guide.practiceKey !== practiceKey,
    ),
  ].slice(0, 3);
